const UNITS = { h: 3600000, m: 60000, s: 1000, ms: 1 };

export function parseDuration(text) {
  if (typeof text !== 'string' || text.length === 0) throw new Error(`bad duration: ${text}`);
  if (!/^(\d+(?:ms|h|m|s))+$/.test(text)) throw new Error(`bad duration: ${text}`);
  let total = 0;
  for (const match of text.matchAll(/\d+(ms|h|m|s)/g)) {
    const unit = match[1];
    const value = Number(match[0].slice(0, -unit.length));
    total += value * UNITS[unit];
  }
  return total;
}

