export function parseDuration(text) {
  if (!text) throw new Error(`bad duration: ${text}`);
  let total = 0;
  let pos = 0;
  while (pos < text.length) {
    const numMatch = /^(\d+)/.exec(text.slice(pos));
    if (!numMatch) throw new Error(`bad duration: ${text}`);
    const num = Number(numMatch[1]);
    pos += numMatch[1].length;

    let unit = null;
    for (const u of ['ms', 'h', 'm', 's']) {
      if (text.slice(pos, pos + u.length) === u) {
        unit = u;
        pos += u.length;
        break;
      }
    }
    if (!unit) throw new Error(`bad duration: ${text}`);
    total += num * UNITS[unit];
  }
  return total;
}

