const VALUES = [
  [1000, 'M'],
  [900, 'CM'],
  [500, 'D'],
  [400, 'CD'],
  [100, 'C'],
  [90, 'XC'],
  [50, 'L'],
  [40, 'XL'],
  [10, 'X'],
  [9, 'IX'],
  [5, 'V'],
  [4, 'IV'],
  [1, 'I'],
];

export function toRoman(n) {
  if (!Number.isInteger(n) || n < 1 || n > 3999) {
    throw new RangeError('Input must be an integer between 1 and 3999');
  }
  let result = '';
  for (const [value, symbol] of VALUES) {
    while (n >= value) {
      result += symbol;
      n -= value;
    }
  }
  return result;
}

const ROMAN_REGEX = /^M{0,3}(CM|CD|D?C{0,3})(XC|XL|L?X{0,3})(IX|IV|V?I{0,3})$/;
const SINGLE_VALUES = {
  I: 1,
  V: 5,
  X: 10,
  L: 50,
  C: 100,
  D: 500,
  M: 1000,
};

export function fromRoman(s) {
  if (typeof s !== 'string' || s.length === 0 || !ROMAN_REGEX.test(s)) {
    throw new Error('Invalid Roman numeral');
  }
  let total = 0;
  let prev = 0;
  for (let i = s.length - 1; i >= 0; i--) {
    const current = SINGLE_VALUES[s[i]];
    if (current < prev) {
      total -= current;
    } else {
      total += current;
      prev = current;
    }
  }
  return total;
}

