const NUMERALS = [
  [1000, 'M'], [900, 'CM'], [500, 'D'], [400, 'CD'],
  [100, 'C'], [90, 'XC'], [50, 'L'], [40, 'XL'],
  [10, 'X'], [9, 'IX'], [5, 'V'], [4, 'IV'], [1, 'I'],
];

export function toRoman(n) {
  if (!Number.isInteger(n) || n < 1 || n > 3999) {
    throw new RangeError('Value must be an integer in range 1..3999');
  }
  let result = '';
  for (const [value, numeral] of NUMERALS) {
    while (n >= value) {
      result += numeral;
      n -= value;
    }
  }
  return result;
}

const ROMAN_VALUES = new Map([
  ['I', 1], ['V', 5], ['X', 10], ['L', 50],
  ['C', 100], ['D', 500], ['M', 1000],
]);

const VALID_ROMAN_RE = /^(M{0,3})(CM|CD|D?C{0,3})(XC|XL|L?X{0,3})(IX|IV|V?I{0,3})$/;

export function fromRoman(s) {
  if (typeof s !== 'string') {
    throw new TypeError('Input must be a string');
  }
  const upper = s.toUpperCase();
  if (!VALID_ROMAN_RE.test(upper)) {
    throw new Error('Invalid Roman numeral');
  }

  let total = 0;
  let prev = 0;
  for (const ch of upper) {
    const val = ROMAN_VALUES.get(ch);
    if (val > prev) {
      total += val - 2 * prev;
    } else {
      total += val;
    }
    prev = val;
  }
  return total;
}

