const NUMERALS = [
  ['M', 1000],
  ['CM', 900],
  ['D', 500],
  ['CD', 400],
  ['C', 100],
  ['XC', 90],
  ['L', 50],
  ['XL', 40],
  ['X', 10],
  ['IX', 9],
  ['V', 5],
  ['IV', 4],
  ['I', 1],
];

export function toRoman(n) {
  if (!Number.isInteger(n) || n < 1 || n > 3999) {
    throw new RangeError('Number must be an integer between 1 and 3999');
  }
  let result = '';
  let remaining = n;
  for (const [symbol, value] of NUMERALS) {
    while (remaining >= value) {
      result += symbol;
      remaining -= value;
    }
  }
  return result;
}

const ROMAN_RE = /^M{0,3}(CM|CD|D?C{0,3})(XC|XL|L?X{0,3})(IX|IV|V?I{0,3})$/;

export function fromRoman(s) {
  if (typeof s !== 'string') {
    throw new Error('Invalid Roman numeral');
  }
  if (!ROMAN_RE.test(s)) {
    throw new Error('Invalid Roman numeral');
  }
  let result = 0;
  let i = 0;
  while (i < s.length) {
    const twoChar = s.slice(i, i + 2);
    const entry = NUMERALS.find(([sym]) => sym === twoChar);
    if (entry) {
      result += entry[1];
      i += 2;
    } else {
      const oneCharEntry = NUMERALS.find(([sym]) => sym === s[i]);
      result += oneCharEntry[1];
      i += 1;
    }
  }
  return result;
}

