files = find_files()

# Find all function definitions in src/
definitions = set()
for path in files:
    if not path.startswith('src/'):
        continue
    with open(path) as f:
        content = f.read()
    content_no_comments = re.sub(r'/\*.*?\*/', '', content, flags=re.DOTALL)
    content_no_comments = re.sub(r'//.*?$', '', content_no_comments, flags=re.MULTILINE)
    for m in re.finditer(r'(?:export\s+)?function\s+([A-Za-z0-9_$]+)', content_no_comments):
        definitions.add(m.group(1))

print("Defined functions in src/:", sorted(definitions))

# Count real call sites (not definitions, not imports, not comments)
call_counts = {name: 0 for name in definitions}
call_locations = {name: [] for name in definitions}

for path in files:
    with open(path) as f:
        lines = f.readlines()

    for line_no, line in enumerate(lines, 1):
        # Skip comments
        stripped = line.strip()
        if stripped.startswith('//') or stripped.startswith('/*') or stripped.startswith('*'):
            continue

        # Remove inline comments for analysis
        code = line.split('//')[0]

        for name in definitions:
            # Look for name followed by '(' but not preceded by function or import keywords
            # Need to avoid matching function definitions and import statements
            for m in re.finditer(r'(?<![A-Za-z0-9_$])' + re.escape(name) + r'\s*\(', code):
                # Check if this is a function definition line
                # Look at the context before the match in the same code portion
                before = code[:m.start()]
                before_stripped = before.strip()
                if before_stripped.endswith('function') or before_stripped.endswith('import'):
