const fs = require('fs');
const path = require('path');

function getAllJsFiles(dir, files = []) {
  const items = fs.readdirSync(dir);
  for (const item of items) {
    const fullPath = path.join(dir, item);
    const stat = fs.statSync(fullPath);
    if (stat.isDirectory()) {
      getAllJsFiles(fullPath, files);
    } else if (item.endsWith('.js')) {
      files.push(fullPath);
    }
  }
  return files;
}

const srcFiles = getAllJsFiles('src');
const allFiles = [...srcFiles, ...getAllJsFiles('test')];

// Find all exported function definitions in src/
const definedFunctions = new Map(); // name -> file

for (const file of srcFiles) {
  const content = fs.readFileSync(file, 'utf8');
  const lines = content.split('\n');
  for (let i = 0; i < lines.length; i++) {
    const line = lines[i];
    // Match export function declarations
    const funcMatch = line.match(/export\s+function\s+([A-Za-z0-9_]+)/);
    if (funcMatch) {
      const name = funcMatch[1];
      definedFunctions.set(name, file);
    }
    // Match export const arrow functions
    const arrowMatch = line.match(/export\s+const\s+([A-Za-z0-9_]+)\s*=/);
    if (arrowMatch) {
      const name = arrowMatch[1];
      definedFunctions.set(name, file);
    }
  }
}

console.log('Defined functions in src/:');
for (const [name, file] of definedFunctions) {
  console.log(`  ${name} in ${file}`);
}

// Count call sites for each defined function
const callCounts = new Map();
for (const name of definedFunctions.keys()) {
  callCounts.set(name, 0);
}

for (const file of allFiles) {
  const content = fs.readFileSync(file, 'utf8');
  const lines = content.split('\n');
  for (let i = 0; i < lines.length; i++) {
    let line = lines[i];

    // Skip comment-only lines
    const trimmed = line.trim();
