import json
import os
import glob

files = sorted(glob.glob("configs/**/*.json", recursive=True))

for path in files:
    with open(path, "r", encoding="utf-8") as f:
        content = f.read()
        data = json.loads(content)

    if data.get("version") == 2:
        print(f"Skipping (already v2): {path}")
        continue

    if data.get("version") != 1:
        print(f"Unexpected version in {path}: {data.get('version')}")
        continue

    new_data = {}
    for key, value in data.items():
        if key == "version":
            new_data["version"] = 2
        elif key == "timeoutMs":
            new_data["timeout_s"] = value / 1000.0
        elif key == "retry":
            new_data["retry"] = {
                "attempts": value["count"],
                "backoff_s": value["backoffMs"] / 1000.0
            }
        elif key == "owners":
            if isinstance(value, str):
                emails = [e.strip().lower() for e in value.split(",")]
                emails = [e for e in emails if e]
                new_data["owners"] = emails
            else:
                new_data["owners"] = value
        else:
            new_data[key] = value

    # Add default retry if missing
    if "retry" not in new_data:
        new_data["retry"] = {"attempts": 0, "backoff_s": 0}

    # Write back with indent=2 and trailing newline
    new_content = json.dumps(new_data, indent=2) + "\n"
    with open(path, "w", encoding="utf-8") as f:
        f.write(new_content)
    print(f"Migrated: {path}")

